fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, 4242);
        let mut i: i32 = 0;
        while i < 6 {
            host::display::state_set(8 + i * 2, i * 70 * 8);
            host::display::state_set(9 + i * 2, (50 + i * 60) * 8);
            i = i + 1;
        }
    }
    let mut gust: i32 = 12 + tab[(t / 5) & 31] * 8 / 127 + tab[(t / 13) & 31] * 4 / 127;
    if gust < 2 { gust = 2; }
    host::display::clear(0x101812);
    let pal: [i32; 3] = [0xc07030, 0xa08020, 0x907040];
    let mut i: i32 = 0;
    while i < 6 {
        let mut x: i32 = host::display::state_get(8 + i * 2);
        let mut y: i32 = host::display::state_get(9 + i * 2);
        let flut: i32 = tab[(t * 2 + i * 11) & 31] * 6 / 127;
        x = x + gust;
        y = y + 3 + flut;
        if x > w * 8 {
            x = -80;
            let seed: i32 = host::display::state_get(2) * 1103515245 + 12345;
            host::display::state_set(2, seed);
            y = (20 + ((seed >> 16) & 4095) % (h - 40)) * 8;
        }
        if y > (h - 8) * 8 { y = 16 * 8; }
        if y < 8 { y = (h - 16) * 8; }
        host::display::state_set(8 + i * 2, x);
        host::display::state_set(9 + i * 2, y);
        host::display::fill_rect(x / 8, y / 8, 12, 8, pal[i % 3]);
        i = i + 1;
    }
    host::display::fill_rect(8, 12, gust * 10, 6, 0x608090);
    host::display::draw_string(8, 24, "WIND", 0x707070, 1);
    host::display::present();
}
